    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as err:
        return err.code, err.headers, err.read()


def seconds_to_wait(headers, body):
    """How long a 429 asks us to wait: the Retry-After header first, then the body."""
    if headers.get("Retry-After") is not None:
        return float(headers["Retry-After"])
    text = body.decode("utf-8", "replace")
    try:
        data = json.loads(text)
    except ValueError:
        data = None
    if isinstance(data, dict):
        for key, value in data.items():
            if "retry" in key.lower() or "wait" in key.lower():
                return float(value)
    match = re.search(r"(\d+(?:\.\d+)?)\s*(?:seconds?|secs?|s)\b", text)
    return float(match.group(1)) if match else None


def call(method, path, auth=True):
    """Return the parsed JSON for a 200 response, or None for a 404.

    Transient failures (5xx, network errors, unparseable 200 bodies, rejected
    tokens) are retried. 429s are waited out for as long as the service says.
    """
    global token, token_fetches
    failures = 0
    while True:
        if auth and token is None:
            token = call("POST", "/token", auth=False)["token"]
            token_fetches += 1
            log(f"  token #{token_fetches} issued")
        stats["requests"] += 1
        try:
            status, headers, body = raw_request(method, path, token if auth else None)
        except (OSError, http.client.HTTPException) as exc:
            status, headers, body = "network", {}, repr(exc).encode()
        if status == 200:
            try:
                return json.loads(body)
            except ValueError:
                status = "bad-body"
        if status == 404:
            return None
        if status == 429:
            wait = seconds_to_wait(headers, body)
            if wait is None:
                raise RuntimeError(f"429 with no readable wait time: {dict(headers)} {body[:300]!r}")
            stats["waits_429"] += 1
            log(f"  {method} {path}: 429, waiting {wait}s as instructed")
            time.sleep(wait)
            continue
        retryable = status in ("network", "bad-body", 401) or (isinstance(status, int) and status >= 500)
        if not retryable:
            raise RuntimeError(f"{method} {path}: unexpected {status}: {body[:300]!r}")
        failures += 1
        if failures > MAX_FAILURES:
            raise RuntimeError(f"{method} {path}: still failing after {failures - 1} retries (last: {status})")
        if status == 401:
            stats["token_rejected"] += 1
            log(f"  {method} {path}: 401, token rejected; fetching a new one")
            token = None
            continue
        delay = min(60, 0.5 * 2 ** failures)
        stats["retries"] += 1
        log(f"  {method} {path}: {status}; retry #{failures} in {delay}s")
        time.sleep(delay)


def cache_file(name):
    return os.path.join(DATA_DIR, name + ".json")


def load_cached(name):
    path = cache_file(name)
    if not os.path.exists(path):
        return None
    with open(path) as fh:
        return json.load(fh)


def store(name, obj):
    path = cache_file(name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path + ".tmp", "w") as fh:
        json.dump(obj, fh)
    os.replace(path + ".tmp", path)


def fetch_order_pages():
    """Every page from 1 to total_pages, in order, checked against page size and next links."""
    pages = []
    total_pages = None
    page_no = 1
    while total_pages is None or page_no <= total_pages:
        name = f"orders/page-{page_no}"
        body = load_cached(name)
        if body is None:
            body = call("GET", f"/orders?page={page_no}")
            if body is None:
                raise RuntimeError(f"page {page_no} returned 404")
            store(name, body)
            log(f"  page {page_no} fetched ({len(body['items'])} items)")
        if body["page"] != page_no:
            raise RuntimeError(f"asked for page {page_no}, got page {body['page']}")
        if total_pages is None:
            total_pages = body["total_pages"]
        if body["total_pages"] != total_pages:
            raise RuntimeError(f"total_pages changed on page {page_no}: {body['total_pages']} != {total_pages}")
        expected_next = f"/orders?page={page_no + 1}" if page_no < total_pages else None
        if body["next"] != expected_next:
            raise RuntimeError(f"page {page_no}: next={body['next']!r}, expected {expected_next!r}")
        count = len(body["items"])
        if (page_no < total_pages and count != PAGE_SIZE) or (page_no == total_pages and not 1 <= count <= PAGE_SIZE):
            raise RuntimeError(f"page {page_no} has {count} items")
        pages.append(body["items"])
        page_no += 1
    return pages, total_pages


def fetch_customer(cid):
    name = f"customers/{cid}"
    record = load_cached(name)
    if record is None:
        record = call("GET", f"/customers/{cid}")
        if record is not None:
            store(name, record)
    return record


def parse_placed_at(text):
    """Return (utc, local): the instant in UTC and the same instant in its own offset."""
    iso = text[:-1] + "+00:00" if text.endswith("Z") else text
    local = datetime.fromisoformat(iso)
    if local.tzinfo is None:
        raise ValueError(f"placed_at has no offset: {text!r}")
    return local.astimezone(timezone.utc), local


def discounted_cents(amount_cents, discount_pct):
    """amount * (100 - pct) / 100, rounded half up to a whole cent, in exact integer arithmetic."""
    quotient, remainder = divmod(amount_cents * (100 - discount_pct), 100)
    return quotient + (1 if remainder >= 50 else 0)


def discounted_cents_decimal(amount_cents, discount_pct):
    """Independent cross-check of discounted_cents using Decimal."""
    value = Decimal(amount_cents) * (100 - discount_pct) / 100
    return int(value.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def main():
    pages, total_pages = fetch_order_pages()
    listed = [item for items in pages for item in items]
    log(f"pages: {len(pages)} (total_pages={total_pages}), listings: {len(listed)}")

    first_seen = {}
    duplicates = 0
    conflicting = []
    statuses = Counter()
    key_sets = Counter()
    for item in listed:
        key_sets[tuple(sorted(item))] += 1
        statuses[item["status"]] += 1
        if not isinstance(item["amount_cents"], int) or isinstance(item["amount_cents"], bool):
            raise RuntimeError(f"non-integer amount: {item}")
        oid = item["id"]
        if oid in first_seen:
            duplicates += 1
            if first_seen[oid] != item:
                conflicting.append(oid)
        else:
            first_seen[oid] = item

    offsets = Counter()
    qualifying = []
    naive_count = 0
    for item in first_seen.values():
        when_utc, when_local = parse_placed_at(item["placed_at"])
        offsets[str(when_local.utcoffset())] += 1
        if item["status"] != "shipped":
            continue
        if NAIVE_START <= when_local.date() <= NAIVE_END:
            naive_count += 1
        if WINDOW_START <= when_utc < WINDOW_END:
            qualifying.append((item, when_utc))
    order_count = len(qualifying)

    customer_ids = sorted({item["customer_id"] for item, _ in qualifying})
    customers = {}
    missing = []
    for cid in customer_ids:
        record = fetch_customer(cid)
        if record is None:
            missing.append(cid)
        else:
            customers[cid] = record
    if missing:
        raise RuntimeError(f"qualifying orders reference unknown customers: {missing}")
    for cid, record in customers.items():
        if (record["id"] != cid or record["region"] not in REGIONS
                or not isinstance(record["discount_pct"], int) or not 0 <= record["discount_pct"] <= 100):
            raise RuntimeError(f"odd customer record: {record}")

    total = 0
    by_region = {region: 0 for region in REGIONS}
    for item, _ in qualifying:
        customer = customers[item["customer_id"]]
        cents = discounted_cents(item["amount_cents"], customer["discount_pct"])
        if cents != discounted_cents_decimal(item["amount_cents"], customer["discount_pct"]):
            raise RuntimeError(f"rounding cross-check failed for {item['id']}")
        total += cents
        by_region[customer["region"]] += cents

    nums = []
    odd_ids = []
    for oid in first_seen:
        match = re.fullmatch(r"ord-(\d+)", oid)
        if match:
            nums.append(int(match.group(1)))
        else:
            odd_ids.append(oid)
    gaps = sorted(set(range(min(nums), max(nums) + 1)) - set(nums)) if nums else []

    log(f"distinct orders: {len(first_seen)}; duplicate listings discarded: {duplicates}")
    log(f"duplicate listings differing from first copy: {len(conflicting)} {conflicting[:10]}")
    log(f"statuses seen (all listings): {dict(statuses)}")
    log(f"placed_at UTC offsets seen (distinct orders): {dict(offsets)}")
    log(f"order key sets seen: {[sorted(k) for k in key_sets]}")
    log(f"ids: ord-{min(nums):04d}..ord-{max(nums):04d}; numbers absent in range: {len(gaps)} {gaps[:10]}; non-standard ids: {odd_ids[:10]}")
    log(f"shipped in UTC window: {order_count}; shipped under naive local-date window: {naive_count}")
    log(f"customers looked up: {len(customer_ids)}; token fetches: {token_fetches}; stats: {dict(stats)}")
    log(f"total_cents={total} order_count={order_count} duplicates_skipped={duplicates} by_region={by_region}")

    if conflicting:
        raise RuntimeError("duplicate listings disagree with their first copy; not writing result")
    if sum(by_region.values()) != total:
        raise RuntimeError("by_region does not add up to total_cents")
    if len({item["id"] for item, _ in qualifying}) != order_count:
        raise RuntimeError("an order was counted twice")

    result = {
        "total_cents": total,
        "order_count": order_count,
        "duplicates_skipped": duplicates,
        "by_region": by_region,
    }
    with open(RESULT_PATH, "w") as fh:
        json.dump(result, fh, indent=2)
        fh.write("\n")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
